// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // Fuzz the 'from' address and the value; the key deciding parameter is the _tos array length = 0.
    // We cannot fuzz an address to act as a callee because a raw EOA always accepts low-level calls.
    // The behavioural difference is that reference reverts on empty _tos, mutant does not. We test that.
    function testFuzz_property(address from, address caddress, uint256 v) public {
        // Keep addresses wide; avoid the zero-address for caddress to ensure call behaviour is admissible
        vm.assume(caddress != address(0));

        // Prepare an empty array for _tos to trigger the require in the reference implementation.
        address[] memory tos = new address[](0);

        // Call transfer and observe whether it reverts or not. The correct contract MUST revert for empty _tos.
        bool ok;
        try c.transfer(from, caddress, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert that the call reverted (i.e., ok == false). The reference contract satisfies this for ALL inputs;
        // the mutant that changed require(_tos.length > 0) to >= 0 will make ok == true for some inputs (empty array),
        // causing this assertion to fail on that mutant.
        assertTrue(!ok);
    }
}
